export function img(category: string, index: number, alt: string) {
  const pool = IMAGE_POOLS[category];
  if (!pool || pool.length === 0) {
    throw new Error(`No images available for category "${category}"`);
  }
  const entry = pool[index % pool.length];
  return { url: entry.path, alt };
}

export function allCreditedImages(): CommonsImage[] {
  const seen = new Set<string>();
  const out: CommonsImage[] = [];
  for (const pool of Object.values(IMAGE_POOLS)) {
    for (const entry of pool) {
      if (!seen.has(entry.path)) {
        seen.add(entry.path);
        out.push(entry);
      }
    }
  }
  return out;
}
